import {cats,today,addDays,uid,defaultPrefs,makeTask,initial,level,bank,suggestedSteps,seed,remaining,reward,validate,openDB,readDB,writeDB,pack,unpack} from './core.js';
import {raccoon,landscape} from './art.js';
import {guideHTML} from './guide.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,db,view='forest',filter='all',weekOffset=0,zone='care',busy=false,saveError='',offline=false,installPrompt,swReg,celebrateUntil=0,toastTimer,calmAction='',companion=false;
const dialog=$('#dialog');
const shop=[{id:'scarf',name:'Bufanda de canela',icon:'🧣',cost:0,type:'wear',desc:'Tu primer abrigo de aventura.'},{id:'hat',name:'Gorrito de otoño',icon:'🍂',cost:30,type:'wear',desc:'Para ideas frescas y orejitas cálidas.'},{id:'flower',name:'Flor de manzanilla',icon:'🌼',cost:25,type:'wear',desc:'Un poquito de primavera contigo.'},{id:'lamp',name:'Farol de luciérnaga',icon:'🏮',cost:40,type:'decor',desc:'Una luz amable junto al sendero.'},{id:'rug',name:'Alfombra terracota',icon:'🧶',cost:35,type:'decor',desc:'Un rincón donde bajar el ritmo.'},{id:'plant',name:'Planta compañera',icon:'🪴',cost:20,type:'decor',desc:'Crecer también lleva su tiempo.'}];
const names={forest:['Tu pequeño gran bosque','Cada paso cuenta. Descansar también.'],day:['Un día a tu ritmo','Pocas misiones. Espacio para respirar.'],week:['La semana, con calma','Tus compromisos a la vista, sin llenar cada rincón.'],shop:['Un refugio muy tuyo','Pequeñas cosas para un bosque que se siente como hogar.'],journal:['Las huellas del camino','Lo que has vivido, sin rachas ni días perdidos.'],guide:['La brújula del bosque','Estrategias, evidencia y cómo cuidar tu progreso.'],settings:['Ajustes del refugio','Tu ritmo, tus datos, tus decisiones.']};
const moodNames={tranquilo:'Tranquilo',cansado:'Cansado',estresado:'Estresado',abrumado:'Abrumado',motivado:'Motivado'};
function toast(text){if(dialog.open&&$('#dialog-feedback'))$('#dialog-feedback').textContent=text;$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function mode(){return Date.now()<celebrateUntil?'celebrating':state.timer?.running?(state.timer.kind==='break'?'resting':'concentrated'):state.mood==='cansado'?'tired':companion?'concentrated':''}
function message(){if(state.restDays.includes(today()))return 'Hoy el bosque descansa contigo. No tienes que ganarte una pausa.';if(state.mood==='abrumado'||state.mood==='estresado')return 'Podemos hacer menos. El bosque seguirá aquí mañana.';if(state.mood==='cansado')return 'Una pausa también es parte del camino. ¿Buscamos una sombra?';return '¿Dos minutitos de tesis? Prometo no robarte las galletas.'}
async function change(fn){if(busy){toast('Guardando el paso anterior; inténtalo de nuevo en un instante.');return false;}busy=true;const before=structuredClone(state);try{fn(state);state.revision=(before.revision||0)+1;await writeDB(db,state,before.revision);saveError='';channel?.postMessage('saved');render();return true}catch(e){state=before;saveError=e.message;toast(e.message);render();return false}finally{busy=false}}
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('rbc-save'):null;
if(channel)channel.onmessage=async()=>{if(!busy&&db){state=validate(await readDB(db));if(dialog.open){dialog.close();toast('Otra pestaña actualizó la partida. Vuelve a abrir el editor para continuar.')}render()}};
function header(){return `<header class="topbar"><span class="eyebrow">UN PASITO A LA VEZ</span><div class="status"><span class="date-text">${new Date().toLocaleDateString('es',{weekday:'long',day:'numeric',month:'long'})}</span><span id="offline-top">${offline?'● Offline listo':'○ Offline sin confirmar'}</span><span class="currency">◈ ${state.coins} bellotas</span></div></header>`}
function render(){if(!state)return;document.body.classList.toggle('no-motion',!state.prefs.animations);if(state.calm){renderCalm();return}const nav=[['forest','⌘','Mi bosque'],['day','☀','Mi día'],['week','▦','Mi semana'],['shop','⌂','Mi refugio'],['journal','✧','Mi aventura'],['guide','☷','Guía y evidencia'],['settings','⚙','Ajustes']];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="./icon.svg" alt=""><div>Raccoon<br>Beats Chaos<small>AVANZA A TU RITMO</small></div></div><nav class="nav" aria-label="Navegación principal">${nav.map(([id,ico,t])=>`<button data-action="nav" data-id="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span>${ico}</span>${t}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="level-mini"><b>${esc(state.name)}</b> · Nivel ${level(state)}<div class="progress" role="progressbar" aria-label="Experiencia para el siguiente nivel" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${state.xp%100}"><i style="width:${state.xp%100}%"></i></div><small>${state.xp%100} / 100 XP · Explorador del bosque</small></div><button class="calm-button" data-action="calm">☁ Estoy abrumado</button><p class="notice muted" style="margin:16px 10px 0">Un pequeño avance.<br>Un descanso merecido.<br>Ambos importan.</p></div></aside><div>${header()}<main class="main" id="main">${saveError?`<div class="error-banner" role="alert">${esc(saveError)} <button data-action="export">Exportar copia</button> <button data-action="reload">Recargar partida guardada</button></div>`:''}<div class="page-heading"><div><span class="eyebrow">${view==='forest'?'BIENVENIDO A CASA': 'RACCOON BEATS CHAOS'}</span><h1>${names[view][0]}</h1><p>${names[view][1]}</p></div>${['forest','day','week'].includes(view)?'<button class="primary" data-action="new">＋ Nueva misión</button>':''}</div>${content()}</main></div><button class="mobile-calm" data-action="calm">☁ Estoy abrumado</button></div>`;tickDisplay()}
function content(){switch(view){case 'forest':return forest();case 'day':return day();case 'week':return week();case 'shop':return wardrobe();case 'journal':return journal();case 'guide':return guideHTML();case 'settings':return settings()}}
function scene(){return `<section class="card scene-card"><div class="scene-head"><div><span class="eyebrow">TU MUNDO CRECE CONTIGO</span><h2>Un respiro en el bosque</h2></div><span class="pill">Nivel ${level(state)}</span></div><div class="scene zone-${zone}">${landscape(state.decor,level(state))}${raccoon(mode(),state.equipped)}<button class="world-node node-thesis ${zone==='thesis'?'selected':''}" data-action="zone" data-id="thesis">📚 Biblioteca del Bosque</button><button class="world-node node-study ${zone==='study'?'selected':''}" data-action="zone" data-id="study">🎓 Universidad del Atardecer</button><button class="world-node node-care ${zone==='care'?'selected':''}" data-action="zone" data-id="care">🌿 Refugio del Mapache</button>${level(state)>=3?'<button class="world-node" style="right:5%;bottom:7%" data-action="pond">El estanque</button>':''}</div><div class="scene-caption"><span>✦</span><p><b>${esc(state.name)} dice:</b> «${message()}»</p></div></section>`}
function forest(){return `<div class="columns"><div>${scene()}<div class="zones">${Object.entries(cats).map(([id,c])=>`<button class="zone ${zone===id?'selected':''}" data-action="zone" data-id="${id}"><span class="ico">${c.emoji}</span><strong>${c.place}</strong><small>${state.logs.filter(x=>x.cat===id&&x.kind==='done').length} misiones completadas</small></button>`).join('')}</div><section class="card"><div class="section-title"><div><h2>Pequeñas misiones de hoy</h2><small>No hace falta hacerlo todo.</small></div><button class="small ghost" data-action="nav" data-id="day">Ver mi día ↗</button></div>${missionList(visibleTasks().filter(t=>filter==='all'||t.cat===filter).slice(0,3))}<button class="small ghost" data-action="suggest">✧ Elegir una sugerencia</button></section></div><aside class="rail">${checkin()}${timerCard()}<div class="gentle"><strong>♡ Descansar también te hace avanzar</strong>Las misiones de bienestar dan las mismas recompensas que las académicas.</div></aside></div>`}
function visibleTasks(){return state.tasks.filter(t=>!t.done&&(!t.date||t.date<=today())).sort((a,b)=>a.priority-b.priority||(a.date||'9999').localeCompare(b.date||'9999'))}
function missionList(tasks){return tasks.length?tasks.map(taskCard).join(''):'<div class="empty">Un espacio libre también es un buen plan.<br>Puedes elegir una misión o simplemente descansar.</div>'}
function taskCard(t){const c=cats[t.cat];return `<article class="mission ${t.cat} ${t.done?'done':''}"><div class="mission-icon">${c.emoji}</div><div class="mission-body"><h3>${esc(t.title)}</h3><div class="meta"><span class="tag">${c.name}</span><span>◷ ${t.duration} min aprox.</span>${t.subject?`<span>${esc(t.subject)}</span>`:''}${t.date&&t.date!==today()?`<span>${t.date<today()?'Pendiente · ':''}${esc(t.date)}</span>`:''}${t.time?`<span>${esc(t.time)}</span>`:''}${t.priority===1?'<span>★ Prioridad</span>':''}${t.repeat!=='none'?`<span>↻ ${t.repeat==='daily'?'Diaria':'Semanal'}</span>`:''}</div><div class="actions">${!t.done?`<button class="small primary" data-action="complete" data-id="${t.id}">✓ Completar</button><button class="small" data-action="partial" data-id="${t.id}" ${t.partialDays.includes(today())?'disabled':''}>Avancé</button><button class="small" data-action="tasktimer" data-id="${t.id}" aria-label="Temporizador para ${esc(t.title)}">▷</button><button class="small" data-action="steps" data-id="${t.id}">Pasitos ${t.steps.filter(s=>s.done).length}/${t.steps.length}</button><button class="small ghost" data-action="edit" data-id="${t.id}">Editar</button>`:`<span class="saved">✓ Guardada · ${esc(t.completedAt||'')}</span>`}</div></div><span class="reward">＋20 XP</span></article>`}
function checkin(){return `<section class="card checkin"><span class="eyebrow">UN MOMENTO PARA TI</span><h3 style="margin-top:7px">¿Cómo estás hoy?</h3><div class="moods">${[['tranquilo','🌤','Tranquilo'],['cansado','🌙','Cansado'],['estresado','🌧','Estrés'],['abrumado','☁','Abrumado'],['motivado','🌱','Motivado']].map(([id,ico,text])=>`<button data-action="mood" data-id="${id}" class="${state.mood===id?'active':''}" aria-pressed="${state.mood===id}"><span>${ico}</span>${text}</button>`).join('')}</div><label class="range-label" for="energy">Mi energía <strong>${state.energy===null?'Sin registrar':state.energy+'/5'}</strong></label><input id="energy" type="range" min="1" max="5" value="${state.energy??3}" aria-label="Energía reportada, de 1 a 5"><label class="range-label" for="stress">Mi estrés <strong>${state.stress===null?'Sin registrar':state.stress+'/5'}</strong></label><input id="stress" type="range" min="1" max="5" value="${state.stress??3}" aria-label="Estrés reportado, de 1 a 5"><p>Opcional y privado. Solo tú decides cómo te sientes.</p>${state.mood||state.energy!==null?'<button class="small ghost" data-action="checkin-save">Guardar registro de hoy</button>':''}</section>`}
function timerCard(){const t=state.timer;return `<section class="card timer-card"><span class="eyebrow">EN BUENA COMPAÑÍA</span><h3 style="margin-top:8px">${t?.kind==='break'?'Descansamos juntos':'Un ratito con '+esc(state.name)}</h3>${raccoon(t?.running?(t.kind==='break'?'resting':'concentrated'):companion?'concentrated':'',state.equipped)}<p class="muted" style="font-size:11px;margin:0">${t?.taskId?esc(state.tasks.find(x=>x.id===t.taskId)?.title||'Sesión libre'):t?'Sesión libre':'El mapache te acompaña. Sin presión.'}</p><div class="clock" data-clock>${formatTime(t?remaining(t):state.prefs.minutes*60000)}</div>${t?`<div class="timer-controls"><button class="primary" data-action="timer-toggle">${remaining(t)<=0?'Ver sesión':t.running?'Ⅱ Pausar':'▷ Reanudar'}</button><button data-action="timer-end">Finalizar</button></div>`:`<div class="timer-presets">${[2,5,10,15,25,45].map(n=>`<button class="${state.prefs.minutes===n?'active':''}" data-action="duration" data-id="${n}">${n}m</button>`).join('')}<button data-action="custom-duration">Otro</button></div><button class="primary" data-action="timer-start">▷ Empezar a mi ritmo</button><button class="small ghost" data-action="companion">${companion?'Terminar compañía':'Compañía sin reloj'}</button>`}<p class="timer-foot">Sin penalizaciones. Tú decides cuándo parar.</p>${!t?'<button class="small ghost" data-action="break">☕ Hacer un descanso</button>':''}</section>`}
function day(){const done=state.tasks.filter(t=>t.done&&t.completedAt===today());return `<div class="columns"><div><div class="card"><div class="section-title"><h2>Tu intención de hoy</h2><button class="small" data-action="plan">Ajustar el día</button></div><p>${state.restDays.includes(today())?'🌿 Día de descanso. Tu progreso está a salvo.':esc(state.priority||'Un paso pequeño y un poco de aire.')}</p><small>Presupuesto académico elegido: ${state.planMinutes} min · No es una obligación.</small><div class="row" style="margin-top:15px"><button class="small" data-action="suggest">✧ Sugerir un plan pequeño</button><button class="small ghost" data-action="restday">${state.restDays.includes(today())?'Volver a día flexible':'Hoy necesito descansar'}</button></div></div><section class="card"><div class="tabs">${[['all','Todo'],['thesis','Tesis'],['study','Carrera'],['care','Bienestar']].map(([id,t])=>`<button class="${filter===id?'active':''}" data-action="filter" data-id="${id}">${t}</button>`).join('')}</div>${missionList(visibleTasks().filter(t=>filter==='all'||t.cat===filter))}</section>${done.length?`<details class="card"><summary>Ya cuenta: ${done.length} ${done.length===1?'misión':'misiones'} de hoy</summary>${missionList(done)}</details>`:''}</div><aside class="rail">${checkin()}${timerCard()}</aside></div>`}
function week(){const d=new Date(today()+'T12:00:00');const start=addDays(today(),-(d.getDay()+6)%7+weekOffset*7);return `<div class="section-title"><div class="row"><button data-action="week-prev" aria-label="Semana anterior">←</button><h2>${new Date(start+'T12:00:00').toLocaleDateString('es',{day:'numeric',month:'long'})} – ${new Date(addDays(start,6)+'T12:00:00').toLocaleDateString('es',{day:'numeric',month:'long'})}</h2><button data-action="week-next" aria-label="Semana siguiente">→</button><button class="small" data-action="week-now">Hoy</button></div><button class="small" data-action="subject">＋ Asignatura</button></div><div class="week">${Array.from({length:7},(_,i)=>{const date=addDays(start,i),dow=new Date(date+'T12:00:00').getDay();return `<section class="day ${date===today()?'today':''}"><h3>${new Date(date+'T12:00:00').toLocaleDateString('es',{weekday:'short'})}</h3><strong class="date">${date.slice(8)}</strong>${state.restDays.includes(date)?'<small>🌿 Descanso</small>':''}${state.subjects.filter(s=>s.days.includes(dow)).map(s=>`<button class="week-task study" data-action="subject-edit" data-id="${s.id}">🎓 ${esc(s.time)} · ${esc(s.name)}</button>`).join('')}${state.tasks.filter(t=>t.date===date).map(t=>`<button class="week-task ${t.cat}" data-action="edit" data-id="${t.id}">${t.done?'✓ ':''}${esc(t.time)} ${esc(t.title)}</button>`).join('')}<button class="small ghost" data-action="newdate" data-id="${date}" aria-label="Añadir misión el ${date}">＋</button></section>`}).join('')}</div><div class="card" style="margin-top:24px"><h2>Tu carrera al atardecer</h2><p class="muted">Después de clases puedes elegir una tarea pequeña o descansar. Los horarios son compromisos; no dan puntos automáticamente.</p>${state.subjects.map(s=>`<div class="section-title"><span>🎓 <b>${esc(s.name)}</b> · ${esc(s.time)} · ${s.days.map(d=>['dom','lun','mar','mié','jue','vie','sáb'][d]).join(', ')}</span><button class="small" data-action="subject-edit" data-id="${s.id}">Editar</button></div>`).join('')||'<small>Añade materias solo si te resulta útil.</small>'}<p class="notice muted">Las misiones recurrentes crean la siguiente ocurrencia al completarlas. Si necesitas mover una, edita su fecha; no se genera una deuda por los días sin usar la app.</p></div>`}
function wardrobe(){return `<div class="columns"><div>${scene()}<div class="section-title"><h2>Objetos con una historia</h2><span class="currency">◈ ${state.coins}</span></div><div class="grid">${shop.map(x=>{const owned=state.inventory.includes(x.id),active=x.type==='wear'?state.equipped===x.id:state.decor.includes(x.id);return `<article class="card"><div class="shop-icon">${x.icon}</div><h3>${x.name}</h3><p class="muted" style="font-size:12px">${x.desc}</p><button class="small ${active?'primary':''}" data-action="shop" data-id="${x.id}" ${!owned&&state.coins<x.cost?'disabled':''}>${owned?(active?'✓ Puesto · quitar':'Colocar'):x.cost+' ◈ · Conseguir'}</button></article>`}).join('')}</div></div><aside><div class="card"><h2>El bosque se abre</h2><p>Tu experiencia nunca disminuye.</p><div class="story"><b>🌊 Claro del estanque · nivel 3</b><p>${level(state)>=3?'Disponible en el mapa. Un lugar para hacer una pausa.':'Un claro tranquilo espera, sin prisa.'}</p></div><div class="story"><b>🐇 Jardín de Bruna · nivel 5</b><p>${level(state)>=5?'Bruna ya visita tu bosque. Toca «Mi aventura» para leer su historia.':'Bruna prepara una merienda bajo los árboles.'}</p></div><small>Sin compras reales ni recompensas aleatorias. Todo puede esperar.</small></div></aside></div>`}
function journal(){const minutes=Math.round(state.sessions.reduce((a,x)=>a+x.seconds,0)/60);return `<div class="grid" style="margin-bottom:24px"><div class="card"><span class="eyebrow">EXPERIENCIA</span><strong class="stat">${state.xp} <small>XP</small></strong><small>Nivel ${level(state)} · sin retrocesos</small></div><div class="card"><span class="eyebrow">PEQUEÑOS LOGROS</span><strong class="stat">${state.logs.filter(x=>x.kind==='done').length}</strong><small>Estudiar y descansar cuentan igual</small></div><div class="card"><span class="eyebrow">SESIONES REGISTRADAS</span><strong class="stat">${minutes} <small>min</small></strong><small>Tiempo transcurrido, no productividad medida</small></div></div><div class="columns"><div class="card"><h2>Historias junto al sendero</h2><div class="story"><b>1 · Una llave y un hogar</b><p>${esc(state.name)} encontró una llave entre las hojas. «Aquí podemos empezar por donde estamos. La tesis ya tiene camino recorrido; no hace falta volver al principio».</p></div>${level(state)>=2?'<div class="story"><b>2 · Olivia y las hojas sueltas</b><p>Olivia, la lechuza, aparece con una sola página. «No traje toda la biblioteca. A veces una página es suficiente». Te invita a revisar un párrafo cuando tengas ganas.</p><button class="small" data-action="story-mission">Aceptar una pequeña misión</button></div>':''}${level(state)>=3?'<div class="story"><b>3 · El claro del estanque</b><p>El sendero se abre hacia el agua. Nadie necesita demostrar nada aquí. Solo hay ondas, hojas y sitio para sentarse.</p><button class="small" data-action="pond">Visitar el estanque</button></div>':''}${level(state)>=5?'<div class="story"><b>5 · La merienda de Bruna</b><p>Bruna dejó una galleta y una nota: «Te guardé un lugar. No necesitas haber terminado tus pendientes». El jardín ya forma parte de tu bosque.</p></div>':''}<h2 style="margin-top:24px">Últimas huellas</h2>${state.logs.slice(-20).reverse().map(x=>`<div class="mission"><span>${cats[x.cat]?.emoji||'✦'}</span><div class="mission-body"><b>${esc(x.title)}</b><div class="meta">${esc(x.date)} · ${x.kind==='partial'?'Avance parcial':x.kind==='step'?'Un pasito':x.kind==='done'?'Completada':'Equilibrio'}</div></div><small>+${x.xp} XP</small></div>`).join('')||'<p class="muted">La primera huella puede ser un descanso.</p>'}</div><aside><div class="card"><h2>Tus insignias</h2><p>${state.logs.some(x=>x.kind==='done')?'🌱 Primer paso':'◌ Primer paso · completa una misión'}</p><p>${state.logs.some(x=>x.kind==='done'&&x.cat==='care')?'☕ Saber parar':'◌ Saber parar · una misión de bienestar'}</p><p>${state.balanceDays.length?'🌻 Equilibrio amable · '+state.balanceDays.length+' días':'◌ Equilibrio amable · una misión en cada área'}</p></div><div class="card"><h3>Registros voluntarios</h3>${state.wellbeing.slice(-10).reverse().map(x=>`<p class="notice">${esc(x.date)} · ${esc(moodNames[x.mood]||'Sin estado')}<br>Energía ${x.energy}/5 · Estrés ${x.stress}/5</p>`).join('')||'<small>No es necesario registrar cómo te sientes.</small>'}</div></aside></div>`}
function settings(){return `<div class="columns"><div><form id="settings-form" class="card"><h2>Tu compañero y tu ritmo</h2><div class="form-grid"><div><label for="petname">Nombre del mapache</label><input id="petname" name="name" maxlength="60" value="${esc(state.name)}" required></div><div><label for="habitual">Sesión habitual (minutos)</label><input id="habitual" name="minutes" type="number" min="1" max="240" value="${state.prefs.minutes}" required></div><div><label for="break-pref">Descanso entre sesiones</label><select id="break-pref" name="breakMinutes">${[5,10,15].map(n=>`<option ${n===state.prefs.breakMinutes?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="chapters">Capítulos u objetivos (opcional)</label><textarea id="chapters" name="chapters" maxlength="10000" placeholder="Puedes dejarlo vacío">${esc(state.chapters)}</textarea></div></div>${[['sounds','Sonido suave al celebrar (app abierta)'],['animations','Animaciones del mapache'],['notifications','Avisos en pantalla al terminar sesiones']].map(([id,title])=>`<label class="check"><input type="checkbox" name="${id}" ${state.prefs[id]?'checked':''}>${title}</label>`).join('')}<small>No enviamos notificaciones con la app cerrada.</small><div class="dialog-actions"><button class="primary" type="submit">Guardar preferencias</button></div></form><div class="card"><h2>Tu partida está contigo</h2><p class="saved">${saveError?'⚠ Revisa el error de guardado':'✓ Guardado en este dispositivo · IndexedDB'}</p><p class="muted">No hay sincronización automática. Exporta una copia antes de cambiar de navegador o borrar sus datos.</p><div class="row"><button class="primary" data-action="export">↓ Exportar partida</button><button data-action="import">↑ Importar partida</button></div><p class="notice muted" style="margin-top:14px">Última exportación: ${state.lastBackup?new Date(state.lastBackup).toLocaleString('es'):'aún no has creado una copia'}. ${!state.lastBackup||Date.now()-state.lastBackup>7*86400000?'Un respaldo esta semana cuidaría tu bosque.':''}</p></div><div class="card"><h2>Preparación offline</h2><p id="offline-detail">${offline?'● Recursos listos para offline en este navegador.':'○ Todavía no se confirmó la descarga de todos los recursos.'}</p><div class="row"><button data-action="offline">Preparar / comprobar offline</button><button data-action="persist">Proteger almacenamiento</button><button data-action="install">Instalar app</button><button data-action="update">Buscar actualización</button></div><p class="notice muted" id="persist-note">El navegador decide si concede almacenamiento persistente. Aun concedido, conserva tus respaldos.</p><p class="notice muted">Prueba abrirla en modo avión después de preparar. La primera carga y las actualizaciones requieren Internet. Abrir index.html directamente no instala la PWA.</p></div></div><aside><div class="card"><h3>Privado por defecto</h3><p class="notice">No se envían tareas ni estados emocionales a servicios externos. No usamos IA remota, analítica ni rastreadores. Los respaldos pueden cifrarse localmente con contraseña.</p><button class="small" data-action="nav" data-id="guide">Leer la guía</button></div><div class="card"><h3>Restablecer con cuidado</h3><p class="notice">Restaurar preferencias conserva misiones, monedas e inventario.</p><button class="small" data-action="reset-prefs">Restaurar preferencias</button><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><p class="notice">Eliminar datos borra la partida de este navegador. Exporta antes si quieres conservarla.</p><button class="small danger" data-action="delete-data">Eliminar todos mis datos</button></div></aside></div>`}
function renderCalm(){const t=state.timer;$('#app').innerHTML=`<main class="calm-screen" id="main"><div class="calm-inner">${raccoon(calmAction==='rest'?'resting':'',state.equipped)}<span class="eyebrow">ESTÁS A SALVO DE TUS PENDIENTES AQUÍ</span><h1>No hace falta resolver<br>todo ahora.</h1><p>El bosque puede esperar. Vamos de a poquito.</p>${calmAction==='rest'?'<div class="breathe-orb">A tu ritmo</div><p class="muted">Si te apetece, respira suavemente sin forzar.<br>También puedes cerrar la app y descansar.</p>':''}${calmAction==='priority'?`<div class="card"><h3>Solo una cosa, cuando quieras</h3><p>${esc(visibleTasks()[0]?.title||'Cuidarte un momento')}</p><button data-action="calm-two">Probar dos minutos</button></div>`:''}${t?`<div class="clock" data-clock>${formatTime(remaining(t))}</div><div class="row" style="justify-content:center"><button data-action="timer-toggle">${t.running?'Pausar':'Reanudar'}</button><button data-action="timer-end">Terminar sin presión</button></div>`:''}<div class="choices"><button data-action="calm-rest">☁ Descansar un momento</button><button data-action="calm-priority">🌱 Ver una única prioridad</button><button data-action="calm-two">◷ Una acción de dos minutos</button></div><button class="ghost" data-action="calm-exit">Volver a mi bosque, cuando quiera →</button></div></main>`;tickDisplay()}
function modal(html){dialog.innerHTML='<div id="dialog-feedback" role="status" aria-live="polite"></div>'+html;if(!dialog.open)dialog.showModal()}
function buttons(submit='Guardar'){return `<div class="dialog-actions"><button type="button" data-action="close">Cancelar</button><button class="primary" type="submit">${submit}</button></div>`}
function taskEditor(id=null,date=today(),template=null){const t=id?state.tasks.find(t=>t.id===id):template||makeTask('',filter==='all'?'thesis':filter,{date});if(!t)return;modal(`<h2>${id?'Editar misión':'Una misión pequeña'}</h2><p>No necesitas revelar el tema ni el contenido de tu tesis.</p><form id="task-form" data-id="${id||''}"><div class="form-grid"><div class="full"><label for="task-title">¿Qué quieres hacer?</label><input id="task-title" name="title" required maxlength="200" value="${esc(t.title)}" placeholder="Por ejemplo: revisar un párrafo"></div><div><label for="task-cat">Lugar</label><select id="task-cat" name="cat">${Object.entries(cats).map(([id,c])=>`<option value="${id}" ${t.cat===id?'selected':''}>${c.place}</option>`).join('')}</select></div><div><label for="task-duration">Minutos aproximados</label><input id="task-duration" name="duration" type="number" min="1" max="240" required value="${t.duration}"></div><div><label for="task-date">Fecha (opcional)</label><input id="task-date" name="date" type="date" value="${t.date}"></div><div><label for="task-time">Hora (opcional)</label><input id="task-time" name="time" type="time" value="${esc(t.time)}"></div><div><label for="task-priority">Prioridad</label><select id="task-priority" name="priority">${[[1,'Una prioridad'],[2,'Normal'],[3,'Puede esperar']].map(([n,l])=>`<option value="${n}" ${t.priority===n?'selected':''}>${l}</option>`).join('')}</select></div><div><label for="task-repeat">Repetición</label><select id="task-repeat" name="repeat">${[['none','Una vez'],['daily','Diaria'],['weekly','Semanal']].map(([v,l])=>`<option value="${v}" ${t.repeat===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="full"><label for="task-subject">Asignatura u objetivo (opcional)</label><input id="task-subject" name="subject" list="subjects" maxlength="120" value="${esc(t.subject)}"><datalist id="subjects">${state.subjects.map(s=>`<option value="${esc(s.name)}">`).join('')}</datalist></div><div class="full"><label for="task-steps">Pasitos editables · uno por línea</label><textarea id="task-steps" name="steps" maxlength="6000">${esc(t.steps.map(s=>s.text).join('\n'))}</textarea><button type="button" class="small ghost" data-action="suggest-steps">✧ Sugerir pasos</button></div></div>${id?`<div class="row" style="margin-top:15px"><button type="button" class="small" data-action="postpone" data-id="${id}">Mover a mañana</button><button type="button" class="small danger" data-action="delete-task" data-id="${id}">Eliminar misión</button></div>`:''}${buttons()}</form>`)}
function suggestions(){const low=state.restDays.includes(today())||state.planMinutes===0||['cansado','abrumado','estresado'].includes(state.mood)||state.energy!==null&&state.energy<=2||state.stress>=4;const afterClass=state.subjects.some(x=>x.days.includes(new Date().getDay())&&x.time<=new Date().toTimeString().slice(0,5));const list=low?[makeTask('Descansar un momento','care',{duration:10}),...(state.planMinutes>0?[makeTask('Abrir el documento de tesis','thesis',{duration:2})]:[])]:[makeTask('Revisar un párrafo','thesis',{duration:Math.max(1,Math.min(Math.floor(state.planMinutes*.6),15))}),makeTask(afterClass?'Preparar los materiales de mañana':'Repasar una asignatura','study',{duration:Math.max(1,Math.min(afterClass?2:10,state.planMinutes-Math.max(1,Math.min(Math.floor(state.planMinutes*.6),15))))}),makeTask('Dar un paseo','care',{duration:10})];modal(`<h2>Un plan que deje espacio</h2><p>${low?'Hoy podemos bajar el ritmo. Puedes elegir solo descanso.':afterClass?'Ya es horario de clases o más tarde: una propuesta más ligera.':'Elige solo lo que te sirva. No se añade nada sin tu elección.'}</p><form id="suggest-form"><div class="steps">${list.map((t,i)=>`<label class="check"><input type="checkbox" name="pick" value="${i}" ${i===0?'checked':''}>${cats[t.cat].emoji} ${esc(t.title)} · ${t.duration} min</label>`).join('')}</div><p>Presupuesto académico: ${state.planMinutes} minutos. Puedes modificar cualquier propuesta después.</p>${buttons('Añadir elegidas')}</form><details style="margin-top:20px"><summary>Explorar más ideas</summary>${Object.entries(bank).map(([c,items])=>`<h3 style="margin-top:15px">${cats[c].name}</h3><div class="row">${items.map(([t,m],i)=>`<button class="small" data-action="bank" data-id="${c}:${i}">${esc(t)}</button>`).join('')}</div>`).join('')}</details>`);$('#suggest-form').onsubmit=async e=>{e.preventDefault();const picks=[...new FormData(e.target).getAll('pick')].map(i=>list[+i]);if(!picks.length){dialog.close();return}if(await change(s=>s.tasks.push(...picks))){dialog.close();toast('Tu plan está listo. Puedes cambiarlo cuando quieras.')}}}
function onboarding(){modal(`<div class="onboarding">${raccoon('',state.equipped)}<span class="eyebrow">UN HOGAR ENTRE LOS ÁRBOLES</span><h2>Hola. ¿Compartimos el camino?</h2><p>Tu tesis ya tiene historia. Aquí podemos continuarla,<br>ir a clases y aprender a descansar.</p><form id="onboard-form"><div class="form-grid"><div><label for="onboard-name">¿Cómo se llama tu mapache?</label><input id="onboard-name" name="name" value="Milo" maxlength="60" required></div><div><label for="onboard-minutes">Un ratito de concentración</label><select id="onboard-minutes" name="minutes">${[2,5,10,15,25,45].map(n=>`<option value="${n}" ${n===15?'selected':''}>${n} minutos</option>`).join('')}</select></div></div><p style="margin-top:16px">Capítulos, materias y horarios son opcionales. Puedes añadirlos después, en Ajustes y Mi semana.</p><div class="dialog-actions" style="justify-content:center"><button type="button" data-action="skip-onboard">Saltar y explorar</button><button class="primary" type="submit">Entrar al bosque →</button></div></form></div>`)}
function subjectEditor(id){const s=state.subjects.find(x=>x.id===id)||{name:'',time:'18:00',days:[1,3]};modal(`<h2>${id?'Editar':'Añadir'} asignatura</h2><form id="subject-form" data-id="${id||''}"><label for="subject-name">Nombre</label><input id="subject-name" name="name" maxlength="120" required value="${esc(s.name)}"><label for="subject-time" style="margin-top:14px">Hora de comienzo</label><input id="subject-time" name="time" type="time" value="${esc(s.time)}" required><div class="row">${['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'].map((d,i)=>`<label class="check"><input type="checkbox" name="days" value="${i}" ${s.days.includes(i)?'checked':''}>${d}</label>`).join('')}</div><p>Para entregas y exámenes, crea una misión con fecha y prioridad.</p>${id?`<button type="button" class="danger small" data-action="subject-delete" data-id="${id}">Eliminar asignatura</button>`:''}${buttons()}</form>`)}
function formatTime(ms){const n=Math.ceil(ms/1000);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function tickDisplay(){document.querySelectorAll('[data-clock]').forEach(e=>e.textContent=formatTime(state.timer?remaining(state.timer):state.prefs.minutes*60000))}
function tone(){if(!state.prefs.sounds)return;try{const a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=660;g.gain.setValueAtTime(.06,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.4);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.4);o.onended=()=>a.close()}catch{}}
async function startTimer(minutes=state.prefs.minutes,taskId=null,kind='focus'){if(state.timer){toast('Termina o pausa la sesión actual antes de iniciar otra.');return}const total=minutes*60000;await change(s=>s.timer={id:uid(),taskId,kind,total,remaining:total,endAt:Date.now()+total,running:true,startedAt:Date.now(),accumulated:0,notified:false});tone()}
function elapsed(t){return Math.min(t.total,t.accumulated+(t.running?Math.max(0,Math.min(Date.now(),t.endAt)-t.startedAt):0))}
function sessionDialog(){if(!state.timer)return;const t=state.timer,task=state.tasks.find(x=>x.id===t.taskId);modal(`<h2>Ese ratito ya cuenta</h2><p>${Math.round(elapsed(t)/60000)} minutos transcurridos. El reloj no decide si terminaste.</p><p>${task?esc(task.title):t.kind==='break'?'Una pausa en el camino.':'Sesión libre con tu mapache.'}</p><div class="steps">${task&&!task.done?`<button class="primary" data-action="session-result" data-id="done">Completé la misión</button> <button data-action="session-result" data-id="partial">Avancé un poco</button>`:''}<button style="margin-top:12px" data-action="session-result" data-id="later">${t.kind==='break'?'Guardar mi descanso':'Continuaré después · guardar sesión'}</button></div><button class="ghost" data-action="close">Volver al reloj</button>`)}
async function finishSession(kind){if(!state.timer)return;const t=structuredClone(state.timer),seconds=Math.round(elapsed(t)/1000);const ok=await change(s=>{s.sessions.push({id:t.id,date:today(),seconds,kind:t.kind,taskId:t.taskId,result:kind});if(kind!=='later'&&t.taskId)reward(s,s.tasks.find(x=>x.id===t.taskId),kind);s.timer=null});if(!ok)return;dialog.close();celebrateUntil=Date.now()+2200;tone();render();toast(kind==='later'?'Sesión guardada. El bosque seguirá aquí.':'Tu avance quedó guardado.');if(t.kind==='focus'&&!state.calm)modal(`<h2>¿Un poco de aire?</h2><p>Una pausa es una opción, no otra obligación.</p><div class="row">${[5,10,15].map(n=>`<button data-action="break-duration" data-id="${n}">${n} min de descanso</button>`).join('')}</div><div class="dialog-actions"><button data-action="close">Seguir a mi ritmo</button></div>`)}
function stepsDialog(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;modal(`<h2>${esc(t.title)}</h2><p>Un pasito recibe 2 XP y 1 bellota una sola vez. Puedes parar aquí.</p><div class="steps">${t.steps.map((s,i)=>`<label class="check"><input type="checkbox" data-step="${i}" data-task="${id}" ${s.done?'checked':''} ${t.done?'disabled':''}>${esc(s.text)}</label>`).join('')||'<p>Aún no hay pasos. Puedes añadirlos en el editor.</p>'}</div><div class="dialog-actions"><button data-action="edit" data-id="${id}">Editar pasos</button><button class="primary" data-action="close">Por ahora está bien</button></div>`)}
function exportDialog(){modal(`<h2>Una copia de tu bosque</h2><p>El archivo puede contener información personal. Guárdalo en un lugar seguro. La contraseña es opcional y no se puede recuperar si la olvidas.</p><form id="export-form"><label for="backup-password">Contraseña para cifrar (opcional, mínimo 8 caracteres)</label><input id="backup-password" name="password" type="password" autocomplete="new-password" minlength="8"><label for="backup-confirm" style="margin-top:12px">Repetir contraseña</label><input id="backup-confirm" name="confirm" type="password" autocomplete="new-password">${buttons('Descargar respaldo')}</form>`)}
function importDialog(){modal(`<h2>Restaurar una partida</h2><p>Se reemplazará esta partida. Exporta primero si quieres conservarla. Validaremos el archivo antes de cambiar nada.</p><form id="import-form"><label for="backup-file">Archivo de respaldo (.json)</label><input id="backup-file" type="file" accept=".json,application/json" required><label for="restore-password" style="margin-top:14px">Contraseña, si lo cifraste</label><input id="restore-password" name="password" type="password" autocomplete="current-password">${buttons('Comprobar archivo')}</form>`)}
function confirmModal(title,text,action,id=''){modal(`<h2>${title}</h2><p>${text}</p><div class="dialog-actions"><button data-action="close">Cancelar</button><button class="danger" data-action="${action}" data-id="${id}">Confirmar</button></div>`)}
let imported=null;
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action:a,id}=b.dataset;const t=state?.tasks.find(x=>x.id===id);try{switch(a){case 'nav':view=id;filter='all';render();window.scrollTo(0,0);break;case 'close':dialog.close();break;case 'reload':location.reload();break;case 'new':taskEditor();break;case 'newdate':taskEditor(null,id);break;case 'edit':taskEditor(id);break;case 'filter':filter=id;render();break;case 'zone':zone=id;filter=id;view='forest';render();toast(cats[id].place+' · puedes elegir una misión o explorar');break;case 'suggest':suggestions();break;case 'bank':{const [cat,i]=id.split(':');const [title,duration]=bank[cat][+i];taskEditor(null,today(),makeTask(title,cat,{duration,steps:suggestedSteps(cat)}));break}case 'suggest-steps':$('#task-steps').value=suggestedSteps($('#task-cat').value).map(s=>s.text).join('\n');break;case 'complete':case 'partial':if(await change(s=>reward(s,s.tasks.find(x=>x.id===id),a==='complete'?'done':'partial'))){celebrateUntil=Date.now()+2500;render();tone();toast(a==='complete'?'✦ ¡Un paso más! +20 XP y 10 bellotas':'🌱 Avanzar también cuenta. +5 XP y 3 bellotas')}break;case 'steps':stepsDialog(id);break;case 'postpone':if(await change(s=>s.tasks.find(x=>x.id===id).date=addDays(today(),1))){dialog.close();toast('Misión movida a mañana. Sin penalización.')}break;case 'delete-task':confirmModal('¿Eliminar esta misión?','Se elimina la tarea, sin quitar experiencia ni recompensas anteriores.','delete-task-confirm',id);break;case 'delete-task-confirm':if(await change(s=>s.tasks=s.tasks.filter(x=>x.id!==id)))dialog.close();break;case 'mood':await change(s=>s.mood=id);break;case 'checkin-save':if(state.energy===null||state.stress===null){toast('Ajusta energía y estrés si quieres guardar un registro completo.');break}if(await change(s=>s.wellbeing.push({id:uid(),date:today(),mood:s.mood,energy:s.energy,stress:s.stress})))toast('Registro guardado, solo en este dispositivo.');break;case 'calm':dialog.close();calmAction='';await change(s=>{s.calm=true;if(s.timer?.running){s.timer.accumulated=elapsed(s.timer);s.timer.remaining=remaining(s.timer);s.timer.running=false}});break;case 'calm-exit':await change(s=>s.calm=false);break;case 'calm-rest':calmAction='rest';render();break;case 'calm-priority':calmAction='priority';render();break;case 'calm-two':if(state.timer)await finishSession('later');await startTimer(2,calmAction==='priority'?visibleTasks()[0]?.id:null);break;case 'duration':await change(s=>s.prefs.minutes=+id);break;case 'custom-duration':modal(`<h2>Tu propio ritmo</h2><form id="duration-form"><label for="custom-minutes">Minutos (1 a 240)</label><input id="custom-minutes" name="minutes" type="number" required min="1" max="240" value="${state.prefs.minutes}">${buttons()}</form>`);break;case 'timer-start':await startTimer();break;case 'tasktimer':await startTimer(t.duration,t.id);break;case 'timer-toggle':if(!state.timer)break;if(remaining(state.timer)<=0){sessionDialog();break}await change(s=>{const x=s.timer;if(x.running){x.accumulated=elapsed(x);x.remaining=remaining(x);x.running=false}else{x.startedAt=Date.now();x.endAt=Date.now()+x.remaining;x.running=true}});break;case 'timer-end':sessionDialog();break;case 'session-result':await finishSession(id);break;case 'companion':companion=!companion;render();break;case 'break':await startTimer(state.prefs.breakMinutes,null,'break');break;case 'break-duration':dialog.close();await startTimer(+id,null,'break');break;case 'plan':modal(`<h2>Un día posible</h2><form id="plan-form"><label for="plan-priority">Una prioridad (opcional)</label><input id="plan-priority" name="priority" maxlength="200" value="${esc(state.priority)}"><label for="plan-minutes" style="margin-top:15px">Tiempo académico que quieres dedicar (minutos)</label><input id="plan-minutes" name="minutes" type="number" min="0" max="480" value="${state.planMinutes}" required><p style="margin-top:12px">Los compromisos se editan en Mi semana. Puedes dedicar cero minutos al trabajo.</p>${buttons()}</form>`);break;case 'restday':await change(s=>{if(s.restDays.includes(today()))s.restDays=s.restDays.filter(d=>d!==today());else s.restDays.push(today())});toast('Tu progreso permanece intacto.');break;case 'week-prev':weekOffset--;render();break;case 'week-next':weekOffset++;render();break;case 'week-now':weekOffset=0;render();break;case 'subject':subjectEditor();break;case 'subject-edit':subjectEditor(id);break;case 'subject-delete':confirmModal('¿Quitar la asignatura?','Sus tareas existentes se conservarán.','subject-delete-confirm',id);break;case 'subject-delete-confirm':if(await change(s=>s.subjects=s.subjects.filter(x=>x.id!==id)))dialog.close();break;case 'shop':{const item=shop.find(x=>x.id===id);if(!item)break;await change(s=>{if(!s.inventory.includes(id)){if(s.coins<item.cost)return;s.coins-=item.cost;s.inventory.push(id)}if(item.type==='wear')s.equipped=s.equipped===id?'':id;else s.decor=s.decor.includes(id)?s.decor.filter(x=>x!==id):[...s.decor,id]});toast('Tu refugio, un poquito más tuyo.');break}case 'pond':modal(`<h2>El claro del estanque</h2><p>Una hoja cae al agua. Puedes tocarla tres veces y observar las ondas, o simplemente quedarte un momento. No hay puntuación ni prisa.</p><div style="text-align:center"><button id="pond-leaf" style="font-size:60px;background:#e1eee3;border-radius:50%;width:160px;height:160px" data-action="leaf" aria-label="Tocar la hoja">🍃</button><p id="pond-caption" style="margin-top:15px">Un instante para mirar.</p></div><div class="dialog-actions"><button data-action="close">Volver al bosque</button></div>`);break;case 'leaf':{const el=$('#pond-leaf');const n=+(el.dataset.count||0)+1;el.dataset.count=n;el.style.boxShadow=`0 0 0 ${Math.min(n,3)*10}px #a6c4ad44`;$('#pond-caption').textContent=['Una pequeña onda.','Otra hoja encuentra su lugar.','Por ahora, esto es suficiente.'][Math.min(n-1,2)];if(n>=3)el.disabled=true;break}case 'story-mission':taskEditor(null,today(),makeTask('Revisar un párrafo con Olivia','thesis',{duration:5}));break;case 'skip-onboard':await change(s=>{seed(s);s.onboarded=true});dialog.close();break;case 'export':exportDialog();break;case 'import':importDialog();break;case 'import-confirm':if(imported){const next=imported;const ok=await change(s=>{const rev=s.revision;Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,next,{revision:rev})});if(ok){imported=null;dialog.close();toast('Partida restaurada. Bienvenido de nuevo al bosque.')}}break;case 'reset-prefs':confirmModal('¿Restaurar preferencias?','Volverán los tiempos, sonidos y animaciones iniciales. Tu progreso se conserva.','reset-prefs-confirm');break;case 'reset-prefs-confirm':if(await change(s=>s.prefs=defaultPrefs()))dialog.close();break;case 'delete-data':modal(`<h2>Eliminar todos mis datos</h2><p>Esta acción borra la partida y la copia de recuperación interna. Los respaldos descargados no se eliminan. Escribe BORRAR para confirmar.</p><form id="delete-form"><label for="delete-word">Confirmación</label><input id="delete-word" name="confirm" required pattern="BORRAR" autocomplete="off">${buttons('Eliminar definitivamente')}</form>`);break;case 'persist':{const yes=await navigator.storage?.persist?.();$('#persist-note').textContent=yes?'✓ Almacenamiento persistente concedido. Conserva igualmente copias de respaldo.':'El navegador no concedió persistencia o no la admite. La app sigue funcionando; exporta respaldos.';break}case 'offline':await prepareOffline();toast(offline?'Recursos comprobados. Prueba abrir en modo avión.':'No se pudo confirmar offline. Revisa la conexión y vuelve a intentar.');break;case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null}else modal(`<h2>Instalar tu bosque</h2><p><b>Android (Chrome):</b> menú ⋮ → Instalar aplicación / Añadir a pantalla de inicio.</p><p><b>iPhone (Safari):</b> Compartir → Añadir a pantalla de inicio.</p><p><b>Computadora (Chrome / Edge):</b> icono de instalación en la barra de direcciones o menú → Instalar.</p><p>Después ábrela, prepara offline y prueba en modo avión. Si no ves la opción, puedes seguir usando la web. La disponibilidad varía por navegador.</p><button data-action="close">Entendido</button>`);break;case 'update':if(swReg){await swReg.update();if(swReg.waiting)modal(`<h2>Hay una actualización</h2><p>Tus datos permanecen en IndexedDB. La app se recargará para abrir la nueva versión.</p><div class="dialog-actions"><button data-action="close">Después</button><button class="primary" data-action="apply-update">Actualizar ahora</button></div>`);else toast('Comprobación solicitada. Si llega una versión, pulsa de nuevo para aplicarla.')}else toast('Primero prepara la app para offline.');break;case 'apply-update':if(swReg?.waiting){reloading=true;swReg.waiting.postMessage({type:'ACTIVATE'});}break}}catch(err){toast(err.message||'No pudimos completar esa acción. Tus datos anteriores se conservan.')}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='energy'||el.id==='stress')await change(s=>s[el.id]=+el.value);if(el.dataset.step!==undefined){const id=el.dataset.task,index=+el.dataset.step,checked=el.checked;const ok=await change(s=>{const t=s.tasks.find(t=>t.id===id),step=t.steps[index];step.done=checked;if(checked&&!t.stepRewards.includes(step.text)){t.stepRewards.push(step.text);s.xp+=2;s.coins++;s.logs.push({id:uid(),date:today(),at:Date.now(),title:step.text,cat:t.cat,kind:'step',xp:2,coins:1})}});if(ok){stepsDialog(id);if(checked)toast('Un pasito guardado. Eso también cuenta.')}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id||f.id==='suggest-form')return;e.preventDefault();const data=new FormData(f);try{switch(f.id){case 'task-form':{const id=f.dataset.id,old=state.tasks.find(t=>t.id===id);const lines=data.get('steps').split('\n').map(s=>s.trim()).filter(Boolean).slice(0,30);if(lines.some(x=>x.length>300))throw Error('Cada paso puede tener hasta 300 caracteres.');const extra={title:data.get('title').trim(),cat:data.get('cat'),duration:+data.get('duration'),date:data.get('date'),time:data.get('time'),priority:+data.get('priority'),repeat:data.get('repeat'),subject:data.get('subject').trim(),steps:lines.map(text=>({text,done:old?.steps.find(s=>s.text===text)?.done||false}))};if(!extra.title)throw Error('Escribe una acción pequeña para tu misión.');if(await change(s=>{if(id)Object.assign(s.tasks.find(t=>t.id===id),extra);else s.tasks.push(makeTask(extra.title,extra.cat,extra))})){dialog.close();toast('Misión guardada automáticamente.')}break}case 'onboard-form':if(await change(s=>{seed(s);s.name=data.get('name').trim()||'Milo';s.prefs.minutes=+data.get('minutes');s.onboarded=true})){dialog.close();toast('Tu bosque está listo. No hay prisa.')}break;case 'duration-form':if(await change(s=>s.prefs.minutes=+data.get('minutes')))dialog.close();break;case 'plan-form':if(await change(s=>{s.priority=data.get('priority');s.planMinutes=+data.get('minutes')}))dialog.close();break;case 'subject-form':{const x={id:f.dataset.id||uid(),name:data.get('name').trim(),time:data.get('time'),days:data.getAll('days').map(Number)};if(!x.name)throw Error('Escribe el nombre de la asignatura.');if(!x.days.length)throw Error('Selecciona al menos un día.');if(await change(s=>{const i=s.subjects.findIndex(a=>a.id===x.id);if(i>=0)s.subjects[i]=x;else s.subjects.push(x)}))dialog.close();break}case 'settings-form':if(await change(s=>{s.name=data.get('name').trim()||'Milo';s.chapters=data.get('chapters');s.prefs={minutes:+data.get('minutes'),breakMinutes:+data.get('breakMinutes'),sounds:data.has('sounds'),animations:data.has('animations'),notifications:data.has('notifications')}}))toast('Preferencias guardadas.');break;case 'export-form':{const pw=data.get('password');if(pw!==data.get('confirm'))throw Error('Las contraseñas no coinciden.');const copy=structuredClone(state);copy.lastBackup=Date.now();const output=await pack(copy,pw);const a=document.createElement('a'),url=URL.createObjectURL(new Blob([output],{type:'application/json'}));a.href=url;a.download=`raccoon-beats-chaos-${today()}${pw?'-cifrado':''}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);await change(s=>s.lastBackup=Date.now());dialog.close();toast('Descarga iniciada. Comprueba que el archivo esté en Descargas.');break}case 'import-form':{const file=$('#backup-file').files[0];if(!file||file.size>25000000)throw Error('Elige un respaldo de menos de 25 MB.');imported=await unpack(await file.text(),data.get('password'));confirmModal('Partida comprobada',`Mapache: ${esc(imported.name)} · Nivel ${level(imported)} · ${imported.tasks.length} misiones. ¿Reemplazar la partida actual?`,'import-confirm');break}case 'delete-form':if(data.get('confirm')!=='BORRAR')return;await new Promise((resolve,reject)=>{const tx=db.transaction('game','readwrite');tx.objectStore('game').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});state=initial();await writeDB(db,state);channel?.postMessage('saved');dialog.close();render();onboarding();break}}catch(err){toast(err.message||'No se pudo guardar. Intenta de nuevo.')}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
async function prepareOffline(){try{if(!('serviceWorker'in navigator))throw Error('No hay Service Worker');swReg=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});await navigator.serviceWorker.ready;const worker=swReg.active;if(!worker)throw Error('Esperando activación');offline=await new Promise(resolve=>{const c=new MessageChannel();const timeout=setTimeout(()=>resolve(false),6000);c.port1.onmessage=e=>{clearTimeout(timeout);resolve(e.data.ready===true)};worker.postMessage({type:'CHECK'},[c.port2])});if($('#offline-top'))$('#offline-top').textContent=offline?'● Offline listo':'○ Offline pendiente';if($('#offline-detail'))$('#offline-detail').textContent=offline?'● Recursos listos para offline en este navegador.':'○ No se pudo confirmar la descarga completa.'}catch{offline=false}}
let reloading=false;if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloading)location.reload();else reloading=true});
async function boot(){try{db=await openDB();db.onversionchange=()=>{db.close();toast('La base de datos cambió. Recarga la aplicación.')};const saved=await readDB(db);state=saved?validate(saved):initial();if(!saved)await writeDB(db,state);render();if(!state.onboarded)onboarding();prepareOffline();setInterval(async()=>{if(!state)return;tickDisplay();const t=state.timer;if(t?.running&&remaining(t)<=0&&!busy){await change(s=>{s.timer.accumulated=s.timer.total;s.timer.remaining=0;s.timer.running=false;s.timer.notified=true});celebrateUntil=Date.now()+2000;tone();render();if(state.prefs.notifications&&!dialog.open)sessionDialog();else toast('Tu ratito terminó. Puedes decidir cómo registrar el avance.')}},1000)}catch(err){$('#app').innerHTML=`<main class="main"><h1>No pudimos abrir el guardado local</h1><p>${esc(err.message)}</p><p>Prueba un navegador normal (sin navegación privada) y permite el almacenamiento de este sitio. No se han borrado datos.</p><button onclick="location.reload()">Volver a intentar</button></main>`}}
boot();
